import Foundation
import NIO
import NIOWebSocket

// Multi-tenant real-time chat server with message filtering

struct TenantConfig {
    let tenantId: String
    let displayNamePattern: String
    let messageFilterPatterns: [String]
    let maxMessageLength: Int
    let rateLimitPerSecond: Int
}

class TenantRegistry {
    private var tenants: [String: TenantConfig] = [:]
    private let lock = NSLock()

    func register(config: TenantConfig) {
        lock.lock()
        defer { lock.unlock() }
        tenants[config.tenantId] = config
    }

    func config(for tenantId: String) -> TenantConfig? {
        lock.lock()
        defer { lock.unlock() }
        return tenants[tenantId]
    }
}

class MessageSanitizer {
    private let compiledPatterns: [String: [NSRegularExpression]]
    private let displayNameValidators: [String: NSRegularExpression]

    init(registry: TenantRegistry, tenantIds: [String]) {
        var patterns: [String: [NSRegularExpression]] = [:]
        var validators: [String: NSRegularExpression] = [:]

        for id in tenantIds {
            guard let config = registry.config(for: id) else { continue }

            // Compile message filter patterns
            let compiled = config.messageFilterPatterns.compactMap { pattern in
                try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive])
            }
            patterns[id] = compiled

            // Compile display name validator
            if let validator = try? NSRegularExpression(
                pattern: config.displayNamePattern,
                options: []
            ) {
                validators[id] = validator
            }
        }

        self.compiledPatterns = patterns
        self.displayNameValidators = validators
    }

    func validateDisplayName(_ name: String, tenantId: String) -> Bool {
        guard name.count <= 64 else { return false }
        guard let validator = displayNameValidators[tenantId] else {
            return false
        }
        let range = NSRange(name.startIndex..., in: name)
        return validator.firstMatch(in: name, options: [], range: range) != nil
    }

    func filterMessage(_ message: String, tenantId: String) -> String {
        guard let patterns = compiledPatterns[tenantId] else {
            return message
        }
        var result = message
        for pattern in patterns {
            let range = NSRange(result.startIndex..., in: result)
            result = pattern.stringByReplacingMatches(
                in: result,
                options: [],
                range: range,
                withTemplate: "[filtered]"
            )
        }
        return result
    }
}

class ChatRoom {
    let roomId: String
    let tenantId: String
    private var participants: [String: WebSocketChannel] = [:]
    private let sanitizer: MessageSanitizer
    private let config: TenantConfig

    init(roomId: String, tenantId: String, sanitizer: MessageSanitizer, config: TenantConfig) {
        self.roomId = roomId
        self.tenantId = tenantId
        self.sanitizer = sanitizer
        self.config = config
    }

    func join(userId: String, displayName: String, channel: WebSocketChannel) -> Bool {
        // Validate display name against tenant-specific pattern
        guard sanitizer.validateDisplayName(displayName, tenantId: tenantId) else {
            return false
        }
        participants[userId] = channel
        broadcast(system: "\(displayName) joined the room")
        return true
    }

    func handleMessage(from userId: String, content: String) {
        guard content.count <= config.maxMessageLength else { return }
        let filtered = sanitizer.filterMessage(content, tenantId: tenantId)
        broadcast(message: filtered, from: userId)
    }

    // Safely encode a dictionary to a JSON string, preventing injection.
    private func encodeJSON(_ object: [String: String]) -> String? {
        guard let data = try? JSONSerialization.data(withJSONObject: object, options: []),
              let json = String(data: data, encoding: .utf8) else {
            return nil
        }
        return json
    }

    private func broadcast(message: String, from userId: String) {
        guard let payload = encodeJSON([
            "type": "message",
            "from": userId,
            "content": message
        ]) else { return }
        for (_, channel) in participants {
            channel.send(payload)
        }
    }

    private func broadcast(system message: String) {
        guard let payload = encodeJSON([
            "type": "system",
            "content": message
        ]) else { return }
        for (_, channel) in participants {
            channel.send(payload)
        }
    }
}

protocol WebSocketChannel {
    func send(_ text: String)
}

// Tenant configuration loader - loads from environment/config
func loadDefaultTenants() -> TenantRegistry {
    let registry = TenantRegistry()

    // Enterprise tenant with strict naming and content policies
    registry.register(config: TenantConfig(
        tenantId: "enterprise-acme",
        displayNamePattern: "^[a-zA-Z]+(\\s[a-zA-Z]+)*$",
        messageFilterPatterns: [
            "(?i)(password|secret|api.?key)\\s*[:=]\\s*\\S+",
            "\\b\\d{3}-\\d{2}-\\d{4}\\b"
        ],
        maxMessageLength: 4096,
        rateLimitPerSecond: 10
    ))

    // Community tenant with relaxed policies
    registry.register(config: TenantConfig(
        tenantId: "community-open",
        displayNamePattern: "^[\\w\\-\\.]{3,30}$",
        messageFilterPatterns: [
            "(?i)\\b(spam|phishing)\\b"
        ],
        maxMessageLength: 2048,
        rateLimitPerSecond: 5
    ))

    return registry
}

// Server bootstrap
func startChatServer(host: String, port: Int) {
    let registry = loadDefaultTenants()
    let sanitizer = MessageSanitizer(
